import * as T from './three.module.js';
const G=window.Game,C=window.Combat,host=document.getElementById('world');let renderer;
try{renderer=new T.WebGLRenderer({antialias:true,powerPreference:'high-performance'});}catch(e){document.getElementById('panel').innerHTML='<h2>The island needs WebGL</h2><p>Open this game in Safari or another browser with 3D graphics enabled.</p>';throw e;}
renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.setClearColor(0x427e92);renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;host.appendChild(renderer.domElement);const scene=new T.Scene();scene.fog=new T.Fog(0x427e92,34,75);const camera=new T.OrthographicCamera(-10,10,10,-10,.1,100);scene.add(new T.HemisphereLight(0xe7f7ff,0x557b60,2.8));const sun=new T.DirectionalLight(0xffedc7,3);sun.position.set(-9,20,6);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-18,right:18,top:18,bottom:-18});sun.shadow.normalBias=.04;scene.add(sun);
const materials={};function mat(c){return materials[c]??=new T.MeshStandardMaterial({color:c,roughness:.8});}function box(w,h,d,c,x,y,z,p=scene){const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat(c));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;p.add(m);return m;}function cyl(r1,r2,h,c,x,y,z,p=scene,n=8){const m=new T.Mesh(new T.CylinderGeometry(r1,r2,h,n),mat(c));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;p.add(m);return m;}function orb(r,c,x,y,z,p=scene){const m=new T.Mesh(new T.IcosahedronGeometry(r,1),mat(c));m.position.set(x,y,z);m.castShadow=true;p.add(m);return m;}function group(x=0,y=0,z=0){const g=new T.Group();g.position.set(x,y,z);scene.add(g);return g;}
box(180,.1,180,0x427e92,0,-1.7,0);box(26,1.6,26,0x957957,0,-.95,0);const grass=box(25.8,.3,25.8,0x83ae78,0,-.08,0);box(5,.03,25.5,0xcec39a,0,.09,0);box(25.5,.03,3.5,0xcec39a,0,.095,0);for(let x=-10;x<=10;x+=2){box(1.4,.025,1.6,0xc4bc92,x,.12,.3);}
const obstacles=[];let seed=42;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}
for(let i=0;i<24;i++){let x=(rand()-.5)*23,z=(rand()-.5)*23;if(Math.abs(x)<3||Math.abs(z)<2.5||Math.hypot(x,z)<5)continue;const g=group(x,0,z);if(i%3!==0){cyl(.16,.25,1.8,0x836441,0,.9,0,g);cyl(0,1,2.1,i%2?0x417e70:0x507e58,0,2.35,0,g,6);cyl(0,.7,1.5,0x70a577,0,3.05,0,g,6);obstacles.push({x,z,r:.65});}else{let rock=orb(.65,0x879aa1,0,.35,0,g);rock.scale.set(1.3,.8,1);obstacles.push({x,z,r:.8});}}
for(let i=0;i<22;i++){const x=(rand()-.5)*25,z=(rand()-.5)*25;if(Math.abs(x)>3&&Math.abs(z)>3){for(let j=0;j<3;j++){const c=cyl(0,.12,.5+rand()*.4,0xaad7c4,x+j*.12,.3,z,scene,5);c.rotation.z=(j-1)*.2;}}}
// Radio tower and safe-looking recharge station.
const station=group(-4.6,0,-4);cyl(1.4,1.6,.22,0x557a82,0,.16,0,station);box(1.2,.95,.75,0x264c64,0,.72,0,station);box(.88,.5,.04,0x75eef0,0,.8,.4,station);cyl(.07,.1,3,0xc0c9b0,0,2.3,0,station);const dish=new T.Mesh(new T.SphereGeometry(.72,16,12,0,Math.PI*2,0,1.15),new T.MeshStandardMaterial({color:0xe5e8d3,side:T.DoubleSide}));dish.position.set(0,3.9,0);dish.rotation.z=.4;station.add(dish);obstacles.push({x:-4.6,z:-4,r:1});let beacon=cyl(.22,.22,.15,0x79eff2,0,4.48,0,station);const pulse=new T.Mesh(new T.TorusGeometry(1.6,.025,6,50),new T.MeshBasicMaterial({color:0x87f5f4,transparent:true,opacity:.45}));pulse.rotation.x=-Math.PI/2;pulse.position.set(-4.6,.16,-4);scene.add(pulse);
function humanoid(enemy=false){const g=new T.Group(),legs=[],arms=[];const body=enemy?0xbb6674:0x3c9aab,trim=enemy?0x683f63:0xf3bc5e;box(.62,.65,.42,body,0,.98,0,g);box(.5,.17,.47,trim,0,.69,0,g);if(enemy){box(.67,.45,.5,0x425064,0,1.54,0,g);box(.52,.12,.04,0xff856f,0,1.58,.27,g);cyl(.04,.04,.25,0x66475f,0,1.9,0,g);orb(.08,0xff8973,0,2.06,0,g);}else{orb(.32,0xf0bf90,0,1.54,0,g);const helmet=orb(.35,0xffd177,0,1.7,-.035,g);helmet.scale.y=.65;box(.48,.18,.07,0x204657,0,1.61,.28,g);box(.52,.47,.22,0x294f73,0,1.02,-.31,g);}for(let s of [-1,1]){const pivot=new T.Group();pivot.position.set(s*.18,.68,0);g.add(pivot);box(.22,.44,.23,enemy?0x334457:0x254862,0,-.25,0,pivot);box(.24,.17,.36,enemy?0x45536b:0xd4e5da,0,-.48,.06,pivot);legs.push(pivot);const a=new T.Group();a.position.set(s*.43,1.22,0);g.add(a);box(.18,.46,.2,body,0,-.19,0,a);orb(.12,enemy?0x4a455c:0xefba85,0,-.42,0,a);arms.push(a);}if(!enemy){box(.2,.2,.67,0x284653,.44,.98,.37,g);box(.14,.12,.2,0x87fff2,.44,.98,.8,g);}g.userData={legs,arms};return g;}
const hero=humanoid();scene.add(hero);const shadow=cyl(.43,.43,.015,0x4d8071,0,.135,0,hero,24);let enemyMeshes=new Map(),bolts=[],sparks=[],shotTimer=0,attackTimer=0,spawnTimer=0,saveTimer=0,emptyTimer=0,time=0;const keys={};addEventListener('keydown',e=>{if(!G.running||['INPUT','SELECT'].includes(document.activeElement.tagName))return;if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)){keys[e.code]=true;e.preventDefault();}});addEventListener('keyup',e=>keys[e.code]=false);function clearKeys(){Object.keys(keys).forEach(k=>keys[k]=false);}addEventListener('blur',()=>{clearKeys();G.input.fire=false;});
function free(x,z){return Math.abs(x)<12.1&&Math.abs(z)<12.1&&!obstacles.some(o=>Math.hypot(x-o.x,z-o.z)<o.r+.32);}
function walk(entity,dx,dz){if(free(entity.x+dx,entity.z))entity.x+=dx;if(free(entity.x,entity.z+dz))entity.z+=dz;}
function sync(){const w=G.world;for(const [id,m]of enemyMeshes)if(!w.enemies.some(e=>e.id===id)){scene.remove(m);enemyMeshes.delete(id);}for(const e of w.enemies){if(!enemyMeshes.has(e.id)){const m=humanoid(true);scene.add(m);enemyMeshes.set(e.id,m);}const m=enemyMeshes.get(e.id);m.position.set(e.x,0,e.z);}}
function burst(x,y,z,color,count=12){for(let i=0;i<count;i++){const m=new T.Mesh(new T.BoxGeometry(.12,.12,.12),new T.MeshBasicMaterial({color}));m.position.set(x,y,z);scene.add(m);sparks.push({m,v:new T.Vector3((Math.random()-.5)*5,Math.random()*3+1,(Math.random()-.5)*5),life:.6});}}
function spawn(){const w=G.world;if(w.spawned>=w.target||w.enemies.length>=Math.min(5,2+w.level))return;let x,z;for(let tries=0;tries<50;tries++){const a=Math.random()*Math.PI*2;x=Math.sin(a)*10.5;z=Math.cos(a)*10.5;if(Math.hypot(x-w.x,z-w.z)>6&&free(x,z))break;}w.enemies.push({id:Date.now()+Math.random(),x,z,hp:2});w.spawned++;burst(x,.4,z,0xffab99,8);sync();}
function shoot(){const w=G.world;if(w.ammo===0){if(emptyTimer<=0){G.toast('Answer a question to recharge your blaster.');emptyTimer=3;}return;}const target=w.enemies.filter(e=>Math.hypot(e.x-w.x,e.z-w.z)<13).sort((a,b)=>Math.hypot(a.x-w.x,a.z-w.z)-Math.hypot(b.x-w.x,b.z-w.z))[0];if(!target)return;if(!C.shoot(w))return;const dx=target.x-w.x,dz=target.z-w.z,n=Math.hypot(dx,dz)||1;hero.rotation.y=Math.atan2(dx,dz);const b=new T.Mesh(new T.SphereGeometry(.14,8,6),new T.MeshBasicMaterial({color:0x8efff4}));b.position.set(w.x,1.05,w.z);scene.add(b);bolts.push({m:b,dx:dx/n*20,dz:dz/n*20,life:1});G.sfx('shot');G.hud();G.save();}
const mm=document.getElementById('minimap').getContext('2d');function map(){const w=G.world;mm.clearRect(0,0,150,150);mm.fillStyle='#183b48';mm.fillRect(0,0,150,150);mm.fillStyle='#729579';mm.fillRect(10,10,130,130);mm.fillStyle='#c4b68c';mm.fillRect(65,10,20,130);mm.fillRect(10,66,130,17);const dot=(x,z,r,c)=>{mm.fillStyle=c;mm.beginPath();mm.arc(75+x*5,75+z*5,r,0,Math.PI*2);mm.fill();};obstacles.forEach(o=>dot(o.x,o.z,3,'#436d61'));dot(-4.6,-4,4,'#ffe282');w.enemies.forEach(e=>dot(e.x,e.z,4,'#ff6c7c'));dot(w.x,w.z,5,'#7cffff');mm.strokeStyle='white';mm.strokeRect(10,10,130,130);}
function resize(){renderer.setSize(innerWidth,innerHeight);const span=innerWidth<600?17:21;camera.left=-span*innerWidth/innerHeight/2;camera.right=-camera.left;camera.top=span/2;camera.bottom=-span/2;camera.updateProjectionMatrix();}addEventListener('resize',resize);resize();G.ready=true;G.hud();const clock=new T.Clock();sync();
function loop(){requestAnimationFrame(loop);const dt=Math.min(clock.getDelta(),.04);if(document.hidden)return;const w=G.world;if(G.rebuild){for(const b of bolts)scene.remove(b.m);bolts=[];sync();G.rebuild=false;spawnTimer=0;attackTimer=0;hero.position.set(w.x,0,w.z);grass.material=mat([0x83ae78,0x80b7a0,0x819d80,0x8796b7,0x9d9d81][(w.level-1)%5]);}if(!G.running)clearKeys();if(G.running){time+=dt;let dx=G.input.x+(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),dz=G.input.z+(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0),len=Math.hypot(dx,dz);if(len>1){dx/=len;dz/=len;}walk(w,dx*dt*4.5,dz*dt*4.5);if(len>.1)hero.rotation.y=Math.atan2(dx,dz);hero.userData.legs.forEach((m,i)=>m.rotation.x=len>.1?Math.sin(time*13+i*Math.PI)*.55:0);hero.userData.arms.forEach((m,i)=>m.rotation.x=len>.1?Math.sin(time*13+i*Math.PI)*.28:0);spawnTimer-=dt;if(spawnTimer<=0){spawn();spawnTimer=2.7;}shotTimer-=dt;emptyTimer-=dt;if((G.input.fire||keys.Space)&&shotTimer<=0){shoot();shotTimer=.27;}attackTimer-=dt;for(const e of [...w.enemies]){const ex=w.x-e.x,ez=w.z-e.z,n=Math.hypot(ex,ez)||1,speed=Math.min(2,1.05+w.level*.09);const ox=e.x,oz=e.z;walk(e,ex/n*speed*dt,ez/n*speed*dt);if(Math.hypot(e.x-ox,e.z-oz)<dt*.2){walk(e,-ez/n*dt*speed,ex/n*dt*speed);}const m=enemyMeshes.get(e.id);if(m){m.rotation.y=Math.atan2(ex,ez);m.userData.legs.forEach((l,i)=>l.rotation.x=Math.sin(time*10+i*Math.PI)*.4);}if(n<1.1&&attackTimer<=0){const dead=C.hurt(w);attackTimer=.8;G.sfx('hit');document.getElementById('damage').style.opacity='1';setTimeout(()=>document.getElementById('damage').style.opacity='0',150);burst(w.x,1,w.z,0xffca8d,5);G.hud();G.save();if(dead){G.question();break;}}}
for(let i=bolts.length-1;i>=0;i--){const b=bolts[i];b.life-=dt;b.m.position.x+=b.dx*dt;b.m.position.z+=b.dz*dt;const hit=w.enemies.find(e=>Math.hypot(e.x-b.m.position.x,e.z-b.m.position.z)<.7);if(hit){const x=hit.x,z=hit.z,killed=C.hit(w,hit.id);burst(x,1,z,killed?0xffd777:0xaffff2,killed?18:6);b.life=0;if(killed){G.sfx('hit');G.hud();G.save();}}if(b.life<=0){scene.remove(b.m);b.m.geometry.dispose();b.m.material.dispose();bolts.splice(i,1);}}if(w.cleared){G.save();G.victory();}saveTimer+=dt;if(saveTimer>1){G.save();saveTimer=0;}sync();}
hero.position.set(w.x,0,w.z);camera.position.set(w.x,19,w.z+15);camera.lookAt(w.x,0,w.z-1);if(G.healBurst){burst(w.x,1,w.z,0xa9ffbd,25);G.healBurst=false;}for(let i=sparks.length-1;i>=0;i--){const p=sparks[i];p.life-=dt;p.m.position.addScaledVector(p.v,dt);p.v.y-=dt*5;p.m.scale.setScalar(Math.max(.01,p.life/.6));if(p.life<=0){scene.remove(p.m);p.m.geometry.dispose();p.m.material.dispose();sparks.splice(i,1);}}pulse.scale.setScalar(1+Math.sin(time*2)*.12);map();renderer.render(scene,camera);}loop();
